package com.nigson.integration.notification;
import java.time.*;
import java.sql.Timestamp;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.transaction.support.TransactionSynchronizationManager;
import tools.jackson.databind.JsonNode;
import com.nigson.integration.platform.*;
import com.nigson.shared.events.EventCodec;
import com.nigson.shared.problem.*;
import com.nigson.shared.security.ProviderHttp;
/** EVT028 durable intake only: notification job, audit and caller inbox commit together; never sends. */
public final class VerificationRequestedHandler implements EventHandler {
 private final UUID generation;private final String account,service,accountHash;private final AuditWriter audit;private final Clock clock;private final String mode,locale;private final Map<String,Integer> revisions;
 public VerificationRequestedHandler(AuditWriter audit,Clock clock,String environment,ProviderHttp.Mode mode,String locale,Map<String,Integer> revisions,String account,String service,UUID generation){if(generation==null||generation.equals(new UUID(0,0)))throw new IllegalArgumentException("MESSAGE_CREATION_GENERATION_REQUIRED");this.generation=generation;this.account=account;this.service=service;this.accountHash=com.nigson.integration.providers.TwilioAccount.fingerprint(mode,account,service);if(!Set.of("local","test","dev","qa","stage","prod").contains(environment)||mode==null||environment.equals("prod")&&mode!=ProviderHttp.Mode.LIVE||mode==ProviderHttp.Mode.MOCK&&!Set.of("local","test").contains(environment)||locale==null||locale.length()>16||revisions==null||!revisions.keySet().equals(Set.of("SMS","WHATSAPP"))||revisions.values().stream().anyMatch(v->v==null||v<1))throw new IllegalArgumentException("MESSAGE_INTAKE_POLICY_REQUIRED");this.audit=Objects.requireNonNull(audit);this.clock=Objects.requireNonNull(clock);this.mode=mode==ProviderHttp.Mode.TEST?"SANDBOX":mode.name();this.locale=locale(locale);this.revisions=Map.copyOf(revisions);}
 public static UUID job(UUID verification){if(verification==null||verification.equals(new UUID(0,0)))throw ApiValues.invalid();return UUID.nameUUIDFromBytes(("contact-verification:"+verification).getBytes(StandardCharsets.US_ASCII));}
 public String eventType(){return "communication.verification.requested.v1";}
 public String handle(JdbcTemplate jdbc,JsonNode event){if(!TransactionSynchronizationManager.isActualTransactionActive())throw new IllegalStateException("LOCAL_TRANSACTION_REQUIRED");EventCodec.decode(EventCodec.JSON.writeValueAsString(event));if(!eventType().equals(event.path("event_type").asString())||!event.path("producer").asString().equals("experience"))throw new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);var payload=event.path("payload");UUID verification=ApiValues.uuid(payload.path("verification_id").asString()),destination=ApiValues.uuid(payload.path("destination_id").asString()),eventId=ApiValues.uuid(event.path("event_id").asString()),correlation=ApiValues.uuid(event.path("correlation_id").asString());String channel=payload.path("channel").asString();if(!destination.equals(ApiValues.uuid(event.path("aggregate_id").asString()))||!revisions.containsKey(channel))throw new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);UUID id=job(verification);String key="contact-verification:"+channel+":"+destination+":"+verification;
  jdbc.execute("SET LOCAL lock_timeout='500ms'");jdbc.execute("SET LOCAL statement_timeout='2s'");jdbc.queryForObject("SELECT pg_advisory_xact_lock(hashtextextended(?,0))",Object.class,"verification-notification:"+verification);
  var existing=jdbc.queryForList("SELECT id,business_key,owner_service,resource_id,destination_id,channel,template_code,template_revision,classification,provider_mode FROM integration.notification_job WHERE id=? OR business_key=? FOR UPDATE",id,key);
  if(!existing.isEmpty()){if(existing.size()!=1)throw conflict();var row=existing.getFirst();if(!id.equals(row.get("id"))||!key.equals(row.get("business_key"))||!"experience".equals(row.get("owner_service"))||!verification.equals(row.get("resource_id"))||!destination.equals(row.get("destination_id"))||!channel.equals(row.get("channel"))||!"CONTACT_VERIFICATION".equals(row.get("template_code"))||!"TRANSACTIONAL".equals(row.get("classification")))throw conflict();var intents=jdbc.queryForList("SELECT d.template_id,d.locale,d.template_snapshot::text,d.template_hash,d.account_sid,d.messaging_service_sid,d.account_hash FROM integration.notification_dispatch d WHERE id=? FOR UPDATE",id);if(intents.size()!=1)throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);var intent=intents.getFirst();var snapshot=EventCodec.JSON.readTree(intent.get("template_snapshot").toString());String savedMode=(String)row.get("provider_mode");ProviderHttp.Mode transport=savedMode.equals("SANDBOX")?ProviderHttp.Mode.TEST:ProviderHttp.Mode.valueOf(savedMode);if(!intent.get("template_hash").equals(EventCodec.hash(snapshot))||!intent.get("account_hash").equals(com.nigson.integration.providers.TwilioAccount.fingerprint(transport,(String)intent.get("account_sid"),(String)intent.get("messaging_service_sid")))||!snapshot.path("id").asString().equals(intent.get("template_id").toString())||!snapshot.path("locale").asString().equals(intent.get("locale"))||snapshot.path("revision").asInt()!=((Number)row.get("template_revision")).intValue()||!snapshot.path("channel").asString().equals(channel))throw new Problem.Failure(ProblemCode.PROVIDER_OUTCOME_UNKNOWN);return "APPLIED";}
  var templates=jdbc.queryForList("SELECT id,body,provider_template_id,variables_schema::text FROM integration.notification_template WHERE code='CONTACT_VERIFICATION' AND revision=? AND locale=? AND channel=? AND classification='TRANSACTIONAL' AND active FOR SHARE",revisions.get(channel),locale,channel);if(templates.size()!=1)throw new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);var template=templates.getFirst();validateTemplate(channel,(String)template.get("body"),(String)template.get("provider_template_id"),EventCodec.JSON.readTree(template.get("variables_schema").toString()));
  jdbc.update("INSERT INTO integration.notification_job(id,created_by,updated_by,business_key,source_event_id,owner_service,resource_id,template_code,template_revision,classification,state,next_attempt_at,channel,destination_id,provider_mode) VALUES (?,'verification-event-worker','verification-event-worker',?,?,'experience',?,'CONTACT_VERIFICATION',?,'TRANSACTIONAL','PENDING',?,?,?,?)",id,key,eventId,verification,revisions.get(channel),Timestamp.from(clock.instant()),channel,destination,mode);
  var snapshot=EventCodec.JSON.createObjectNode();snapshot.put("id",template.get("id").toString());snapshot.put("code","CONTACT_VERIFICATION");snapshot.put("revision",revisions.get(channel));snapshot.put("locale",locale);snapshot.put("channel",channel);snapshot.put("classification","TRANSACTIONAL");snapshot.put("body",(String)template.get("body"));snapshot.put("providerTemplateId",(String)template.get("provider_template_id"));snapshot.set("variablesSchema",EventCodec.JSON.readTree(template.get("variables_schema").toString()));
  jdbc.update("INSERT INTO integration.notification_dispatch(id,created_by,updated_by,template_id,locale,template_snapshot,template_hash,account_sid,messaging_service_sid,account_hash,generation,source_occurred_at,correlation_id) VALUES (?,'verification-event-worker','verification-event-worker',?,?,?::jsonb,?,?,?,?,?,?,?)",id,template.get("id"),locale,EventCodec.JSON.writeValueAsString(snapshot),EventCodec.hash(snapshot),account,service,accountHash,generation,Timestamp.from(Instant.parse(event.path("occurred_at").asString())),correlation);
  audit.append("verification-event-worker",AuditValues.ActorKind.SYSTEM,AuditValues.Action.QUEUE_REPLAY,AuditValues.Resource.NOTIFICATION,id,correlation,AuditValues.Reason.RECONCILIATION,null,Map.of("state","PENDING","channel",channel,"revision",revisions.get(channel)),null);return "APPLIED";
 }
 /** Flat literal verification templates only; no expression engine or arbitrary recipient schema. */
 public static void validateTemplate(String channel,String body,String providerTemplate,JsonNode schema){if(body==null||body.isBlank()||body.length()>1600||body.codePoints().anyMatch(c->Character.isISOControl(c)&&c!='\n')||schema==null||!schema.isObject()||!schema.propertyNames().equals(Set.of("type","additionalProperties","properties","required"))||!schema.path("type").asString().equals("object")||!schema.path("additionalProperties").isBoolean()||schema.path("additionalProperties").asBoolean()||!schema.path("properties").isObject()||!schema.path("properties").propertyNames().equals(Set.of("code","expiresAt"))||!schema.path("required").isArray()||schema.path("required").size()!=2)throw rule();var required=new HashSet<String>();for(var v:schema.path("required"))if(!v.isString()||!required.add(v.asString()))throw rule();if(!required.equals(Set.of("code","expiresAt")))throw rule();for(String field:required){var value=schema.path("properties").path(field);if(!value.isObject()||!value.propertyNames().equals(Set.of("type","maxLength"))||!value.path("type").asString().equals("string")||!value.path("maxLength").isIntegralNumber()||!value.path("maxLength").canConvertToInt()||value.path("maxLength").asInt()!= (field.equals("code")?6:40))throw rule();}String literal=body.replace("{{code}}","").replace("{{expiresAt}}","");if(!body.contains("{{code}}")||literal.contains("{")||literal.contains("}"))throw rule();if(channel.equals("WHATSAPP")&&(providerTemplate==null||!providerTemplate.matches("HX[a-fA-F0-9]{32}")))throw rule();if(!Set.of("SMS","WHATSAPP").contains(channel))throw rule();}
 private static Problem.Failure conflict(){return new Problem.Failure(ProblemCode.IDEMPOTENCY_HASH_MISMATCH);}
 private static Problem.Failure rule(){return new Problem.Failure(ProblemCode.NOTIFICATION_RULE_VIOLATION);}
 private static String locale(String value){try{var result=new Locale.Builder().setLanguageTag(value).build();if(result.getLanguage().isBlank())throw new IllegalArgumentException();return result.toLanguageTag();}catch(RuntimeException invalid){throw new IllegalArgumentException("MESSAGE_INTAKE_POLICY_REQUIRED");}}
}
